parameters.jsCode:
// Filtert auf ALLE Zeilen, die auf eine Headline/Subline-Auswahl per Matrix
// warten (koennen mehrere gleichzeitig sein - die Vorgangsnummer ist seit
// V2 Teil des Codes, deshalb keine Mehrdeutigkeit mehr bei parallelen Wartern),
// und liest je Zeile die Kandidaten sowie den Zeitstempel des Matrix-Posts aus
// visualJson.headlineCandidates / visualJson.candidatesPostedAt.
function parseObj(v) {
  if (!v) return {};
  if (typeof v === 'object' && !Array.isArray(v)) return v;
  try {
    const p = JSON.parse(String(v));
    return (p && typeof p === 'object' && !Array.isArray(p)) ? p : {};
  } catch (e) {
    return {};
  }
}

const waiting = items.filter(item => String(item.json.headlineChoiceStage || '').trim() === 'awaiting_headline_choice');

// FIX 2026-07-25: immer mindestens 1 Item zurueckgeben (Platzhalter ohne vorgangKey,
// wird von "Finde erinnerungsfällige Vorgänge" automatisch uebersprungen und von
// "Finde Sat-Antwort" ueber $()-Referenz separat gelesen), damit dieser Node
// zuverlaessig als "ausgefuehrt" gilt, wenn Matrix Nachrichten lesen ueber den
// Merge-Knoten darauf wartet - sonst race-abhaengiger 'Node hasnt been executed'-Fehler.
if (waiting.length === 0) {
  return [{ json: { _noHeadlinesWaiting: true } }];
}

return waiting.map(item => {
  const row = item.json;
  const vj = parseObj(row.visualJson);
  const candidates = Array.isArray(vj.headlineCandidates) ? vj.headlineCandidates : [];
  const candidatesPostedAt = vj.candidatesPostedAt || null;
  const lastReminderAt = vj.lastReminderAt || null;
  const reminderCount = Number(vj.reminderCount || 0);
  // FIX 2026-08-01: kernbotschaft mit durchreichen, damit "Finde erinnerungsfaellige
  // Vorgaenge" eine Erinnerung mit demselben Kontext bauen kann wie die urspruengliche
  // Umfrage in P3e (die hatte Kernbotschaft + satireBrief/groundingHintText pro Kandidat,
  // die Erinnerung bisher nur die nackte Code:Headline-Subline-Zeile).
  const kernbotschaft = vj.kernbotschaft || '';
  return {
    json: {
      ...row,
      _headlineCandidates: candidates,
      _candidatesPostedAt: candidatesPostedAt,
      _lastReminderAt: lastReminderAt,
      _reminderCount: reminderCount,
      _kernbotschaft: kernbotschaft
    }
  };
});

// Sucht in den zuletzt gelesenen Matrix-Nachrichten nach einer Antwort, die
// exakt (bis auf optionales '#' und Leerzeichen) einem Kandidaten-Code
// entspricht - der Code enthaelt seit V2 die Vorgangsnummer
// (z.B. "2026-192-K2"), deshalb ist die Zuordnung eindeutig, auch wenn
// mehrere Vorgaenge gleichzeitig auf eine Auswahl warten.
// Die blosse Vorgangsnummer mit "-X"-Suffix (z.B. "2026-192-X", OHNE Kandidat)
// ist kein Auswahl-, sondern ein Reroll-Wunsch fuer den GANZEN Vorgang: statt
// der Kandidaten wird er auf visualPromptStage='needs_prompt' zurueckgesetzt
// (imageHeadline/imageSubline geleert), damit P2 beim naechsten planmaessigen
// Lauf komplett neue Headline/Subline-Varianten erzeugt (siehe ZIEL_STATUS in
// "Filtere Visual-Status"). Welcher der vier Kandidaten dabei angegeben wird,
// spielt keine Rolle - deshalb wird fuer den Reroll nur die Vorgangsnummer
// gematcht, kein einzelner Kandidaten-Code.
// Findet sich keine gültige, neue Antwort, endet der Lauf ohne Änderung -
// der nächste Poll (alle 15 Min) versucht es erneut.
function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function normCode(v) { return safeStr(v).toLowerCase().replace(/^#/, '').replace(/\s+/g, ''); }
function vnCodeOf(row) { return safeStr(row.vorgangsnummer).replace(/[^0-9A-Za-z]+/g, '-').replace(/^-+|-+$/g, ''); }

const waitingRows = $('Finde wartenden Vorgang').all().map(i => i.json || {});

// Kandidaten-Ebene (fuer normale Auswahl) und Vorgangs-Ebene (fuer Reroll),
// je mit eigener candidatesPostedAt-Grenze (eine Antwort zaehlt nur, wenn sie
// NACH dem Posten der Kandidaten fuer genau diesen Vorgang kam).
const allCandidates = [];
const allRows = [];
for (const row of waitingRows) {
  const candidates = Array.isArray(row._headlineCandidates) ? row._headlineCandidates : [];
  const postedAtMs = row._candidatesPostedAt ? Date.parse(row._candidatesPostedAt) : 0;
  for (const c of candidates) {
    allCandidates.push({ row, candidate: c, postedAtMs, normCode: normCode(c.code) });
  }
  if (candidates.length > 0) {
    allRows.push({ row, postedAtMs, normVnCode: normCode(vnCodeOf(row)) });
  }
}

const chunk = Array.isArray(items[0].json.chunk) ? items[0].json.chunk : [];

const matches = [];
for (const ev of chunk) {
  if (!ev || ev.type !== 'm.room.message') continue;
  const content = ev.content || {};
  if (content.msgtype !== 'm.text') continue;
  const ts = Number(ev.origin_server_ts || 0);
  let replyNorm = normCode(content.body);
  if (!replyNorm) continue;

  let isRerollRequest = false;
  if (replyNorm.endsWith('-x')) {
    isRerollRequest = true;
    replyNorm = replyNorm.slice(0, -2);
  }

  if (isRerollRequest) {
    for (const entry of allRows) {
      if (entry.postedAtMs && ts <= entry.postedAtMs) continue;
      if (entry.normVnCode === replyNorm) {
        matches.push({ ts, isRerollRequest: true, row: entry.row });
      }
    }
  } else {
    for (const entry of allCandidates) {
      if (entry.postedAtMs && ts <= entry.postedAtMs) continue;
      if (entry.normCode === replyNorm) {
        matches.push({ ts, isRerollRequest: false, row: entry.row, candidate: entry.candidate });
      }
    }
  }
}

if (matches.length === 0) {
  return [];
}

// FIX 2026-07-25 (Nutzerwunsch): bisher wurde je Durchlauf nur die AELTESTE gueltige Antwort
// verarbeitet (matches[0]) - bei mehreren gleichzeitig wartenden Umfragen kam pro Lauf nur eine
// einzige Bestaetigung zurueck, der Rest blieb bis zu den naechsten Laeufen stumm in der
// Warteschlange. Das sah wie ein Fehler aus, obwohl die Nachrichten korrekt gelesen wurden.
// Jetzt werden ALLE im Fenster gefundenen gueltigen Antworten in diesem einen Durchlauf
// verarbeitet - bei mehreren Antworten fuer DENSELBEN Vorgang gewinnt weiterhin die aelteste
// (z.B. wenn jemand zweimal geantwortet hat), aber unterschiedliche Vorgaenge laufen jetzt
// parallel durch, jeder bekommt sofort seine eigene Bestaetigung.
matches.sort((a, b) => a.ts - b.ts);
const chosenByVorgang = new Map();
for (const m of matches) {
  const vk = safeStr(m.row.vorgangKey);
  if (!vk || chosenByVorgang.has(vk)) continue; // aelteste Antwort pro Vorgang gewinnt (matches ist bereits nach ts sortiert)
  chosenByVorgang.set(vk, m);
}

function safeArr(v) { return Array.isArray(v) ? v : []; }

const out = [];
for (const chosen of chosenByVorgang.values()) {
  const vorgangKeySafe = safeStr(chosen.row.vorgangKey).replace(/[^a-zA-Z0-9]/g, '');

  if (chosen.isRerollRequest) {
    out.push({
      json: {
        ...chosen.row,
        imageHeadline: '',
        imageSubline: '',
        headlineChoiceStage: 'needs_kernbotschaft',
        visualPromptStage: '',
        imageStage: safeStr(chosen.row.imageFinalPath) ? 'composed' : 'not_started',
        _matrixAction: 'reroll',
        _confirmMessage: '🔄 Ok, für ' + safeStr(chosen.row.vorgangsnummer) + ' - ' + safeStr(chosen.row.title) + ' finde ich eine komplett neue Kernbotschaft. Das dauert bis zum nächsten planmäßigen Durchlauf. Es wird weiterhin nichts veröffentlicht, bis du eine Formulierung bestätigst.',
        _confirmTxnId: 'hdl_confirm_' + vorgangKeySafe + '_reroll_' + Date.now(),
        // FIX 2026-08-01 (Nutzerwunsch "Lernagent soll von meinen Entscheidungen lernen"):
        // Kandidatenliste durchreichen, damit ein nachgelagerter Schritt einen Lernbeispiel-
        // Eintrag bauen kann (hier: Reroll = alle angebotenen Kandidaten abgelehnt).
        _learnAllCandidates: JSON.stringify(safeArr(chosen.row._headlineCandidates)),
        _learnChosenCode: ''
      }
    });
    continue;
  }

  // Cutover 2026-07-18: Kandidaten tragen jetzt das volle Satire-Agent-Varianten-Feld-Set
  // (nicht mehr nur imageHeadline/imageSubline aus P5s alter Headline-Generierung). Die
  // gewaehlte Variante ueberschreibt die kompletten satire*-Spalten, damit Bild-Agent (P5) mit
  // genau der Variante arbeitet, die der Mensch fuers Bild ausgewaehlt hat - unabhaengig davon,
  // welche Variante P3 automatisch fuer den Text gewaehlt hatte.
  out.push({
    json: {
      ...chosen.row,
      imageHeadline: safeStr(chosen.candidate.imageHeadline),
      imageSubline: safeStr(chosen.candidate.imageSubline),
      satireBrief: safeStr(chosen.candidate.satireBrief),
      satireAngle: safeStr(chosen.candidate.satireAngle),
      satirePunchlines: JSON.stringify(safeArr(chosen.candidate.satirePunchlines)),
      satireTarget: safeStr(chosen.candidate.satireTarget),
      satireIntensity: Number(chosen.candidate.satireIntensity) || 0,
      satireDoNotClaim: JSON.stringify(safeArr(chosen.candidate.satireDoNotClaim)),
      satireSafetyNote: safeStr(chosen.candidate.satireSafetyNote),
      headlineChoiceStage: 'headline_selected',
      contentStage: 'needs_content',
      imageStage: safeStr(chosen.row.imageFinalPath) ? 'composed' : 'not_started',
      _matrixAction: 'select',
      _confirmMessage: '✅ Danke! Für ' + safeStr(chosen.row.vorgangsnummer) + ' - ' + safeStr(chosen.row.title) + ' wurde übernommen: "' + safeStr(chosen.candidate.imageHeadline) + '" - "' + safeStr(chosen.candidate.imageSubline) + '". Text und Bild werden jetzt freigegeben und beim nächsten planmäßigen Durchlauf veröffentlicht.',
      _confirmTxnId: 'hdl_confirm_' + vorgangKeySafe + '_select_' + normCode(safeStr(chosen.candidate.code)) + '_' + Date.now(),
      // FIX 2026-08-01 (Nutzerwunsch "Lernagent soll von meinen Entscheidungen lernen"):
      // volle Kandidatenliste + gewaehlter Code durchreichen, damit ein nachgelagerter Schritt
      // die tatsaechliche menschliche Entscheidung als Lernbeispiel speichern kann.
      _learnAllCandidates: JSON.stringify(safeArr(chosen.row._headlineCandidates)),
      _learnChosenCode: safeStr(chosen.candidate.code)
    }
  });
}

return out;

// Prueft, welche wartenden Vorgaenge laenger als REMINDER_INTERVAL_MS keine
// neue Nachricht bekommen haben, und baut dafuer eine Erinnerung mit den
// bereits bestehenden Kandidaten (keine neue KI-Generierung, kein neuer Text).
// Stoppt nach MAX_REMINDERS, damit ein unbeantworteter Vorgang nicht endlos nervt.
//
// FIX (Architekturpruefung 2026-07-22, Befund F3): bisher wurde ein Vorgang nach
// Erreichen von MAX_REMINDERS stillschweigend uebersprungen - unsichtbar in der
// Status-Uebersicht, ohne jede Markierung. Jetzt wird EINMALIG (nicht bei jedem
// 15-Minuten-Lauf erneut) ein sichtbarer Hinweis in visualJson.workflow
// hinterlegt (reminderExhausted/reminderExhaustedAt) - keine neue DB-Spalte
// noetig, da visualJson bereits existiert und bereits von diesem Workflow
// geschrieben wird. headlineChoiceStage bleibt dabei bewusst unveraendert:
// der Mensch kann jederzeit trotzdem noch per Matrix antworten, es werden nur
// keine weiteren automatischen Erinnerungen mehr verschickt.
const REMINDER_INTERVAL_MS = 12 * 60 * 60 * 1000;
const MAX_REMINDERS = 5;

function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function parseObj(v) {
  if (!v) return {};
  if (typeof v === 'object' && !Array.isArray(v)) return v;
  try { const p = JSON.parse(String(v)); return (p && typeof p === 'object' && !Array.isArray(p)) ? p : {}; }
  catch (e) { return {}; }
}

const now = Date.now();
const due = [];

for (const item of items) {
  const row = item.json;
  const reminderCount = Number(row._reminderCount || 0);

  if (reminderCount >= MAX_REMINDERS) {
    const vj = parseObj(row.visualJson);
    const alreadyMarkedExhausted = !!(vj.workflow && vj.workflow.reminderExhausted === true);
    if (alreadyMarkedExhausted) continue;

    vj.workflow = {
      ...(vj.workflow && typeof vj.workflow === 'object' && !Array.isArray(vj.workflow) ? vj.workflow : {}),
      reminderExhausted: true,
      reminderExhaustedAt: new Date().toISOString()
    };

    due.push({
      json: {
        ...row,
        visualJson: JSON.stringify(vj),
        _reminderExhaustedOnly: true
      }
    });
    continue;
  }

  const lastPromptMs = row._lastReminderAt
    ? Date.parse(row._lastReminderAt)
    : (row._candidatesPostedAt ? Date.parse(row._candidatesPostedAt) : 0);
  if (!lastPromptMs || (now - lastPromptMs) < REMINDER_INTERVAL_MS) continue;

  const candidates = Array.isArray(row._headlineCandidates) ? row._headlineCandidates : [];
  if (candidates.length === 0) continue;

  const nextReminderCount = reminderCount + 1;
  // FIX 2026-08-01: Erinnerung war deutlich knapper als die urspruengliche Umfrage in P3e
  // (nur Code:Headline-Subline, ohne Kernbotschaft-Kontext und ohne satireBrief/
  // groundingHintText pro Kandidat) - nicht absichtlich, siehe Kommentar oben ("keine neue
  // KI-Generierung, kein neuer Text" meinte nur keinen neuen Kandidaten-Text, nicht weniger
  // Kontext). Jetzt an dasselbe Format wie die Original-Umfrage angeglichen.
  const kernbotschaft = safeStr(row._kernbotschaft);
  const lines = [
    '⏰ Erinnerung (' + nextReminderCount + '/' + MAX_REMINDERS + ') - noch offen: ' + safeStr(row.vorgangsnummer) + ' - ' + safeStr(row.title),
    ''
  ];
  if (kernbotschaft) {
    lines.push(kernbotschaft, '');
  }
  lines.push('🎨 Formulierungen zur Auswahl:', '');
  for (const c of candidates) {
    lines.push(safeStr(c.code) + ': ' + safeStr(c.imageHeadline) + ' - ' + safeStr(c.imageSubline));
    if (c.satireBrief) lines.push('   ' + safeStr(c.satireBrief));
    if (c.groundingHintText) lines.push('   ' + safeStr(c.groundingHintText));
  }
  lines.push('');
  const exampleCode = candidates.length > 0 ? safeStr(candidates[0].code) : '';
  const vnCode = safeStr(row.vorgangsnummer).replace(/[^0-9A-Za-z]+/g, '-').replace(/^-+|-+$/g, '');
  lines.push('Antworte mit dem gewuenschten Code (z.B. ' + exampleCode + '), um die Auswahl zu bestaetigen, oder mit \'' + vnCode + '-X\' fuer komplett neue Vorschlaege (Vorgangsnummer + -X, ohne Kandidat).');

  const vorgangKeySafe = safeStr(row.vorgangKey).replace(/[^a-zA-Z0-9]/g, '');
  const txnId = 'hdl_remind_' + vorgangKeySafe + '_r' + nextReminderCount;

  due.push({
    json: {
      ...row,
      matrixReminderMessage: lines.join('\n'),
      matrixReminderTxnId: txnId,
      _nextReminderCount: nextReminderCount,
      _reminderExhaustedOnly: false
    }
  });
}

return due;

// Stellt den Vorgangskontext nach dem Matrix-Versand wieder her (gleiches Muster
// wie "Stelle Kontext nach Matrix wieder her" in P2) - der HTTP-Node ersetzt das
// Item-JSON durch die rohe Matrix-API-Antwort und wuerde sonst vorgangKey,
// reminderCount usw. verlieren, sodass "Speichere Erinnerung" keine Zeile findet.
function parseObj(v) {
  if (!v) return {};
  if (typeof v === 'object' && !Array.isArray(v)) return v;
  try { const p = JSON.parse(String(v)); return (p && typeof p === 'object' && !Array.isArray(p)) ? p : {}; } catch (e) { return {}; }
}

const response = $input.item.json || {};
const base = $('Finde erinnerungsfällige Vorgänge').item.json || {};

const hasError = !!(
  response.error ||
  response.errcode ||
  (response.statusCode && Number(response.statusCode) >= 400)
);
const eventId = response.event_id || response.eventId || '';

const existingVisual = parseObj(base.visualJson);

return {
  json: {
    ...base,
    visualJson: JSON.stringify({
      ...existingVisual,
      lastReminderAt: hasError ? (base._lastReminderAt || existingVisual.candidatesPostedAt || null) : new Date().toISOString(),
      reminderCount: hasError ? Number(base._reminderCount || 0) : base._nextReminderCount
    }),
    matrixReminderSentOk: !hasError && !!eventId,
    matrixReminderError: hasError ? (response.error || response.errcode || 'Matrix-Versand fehlgeschlagen') : ''
  }
};

// Filtert auf ALLE Zeilen, die dauerhaft blockiert sind (sharepicNeedStage
// topic_error oder blocked_source_lock) und per Matrix-Antwort geklaert
// werden koennen (2026-07-24 ergaenzt, siehe PROJECT_COORDINATION.md).
function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }

const waiting = items.filter(item => ['topic_error', 'blocked_source_lock'].includes(safeStr(item.json.sharepicNeedStage)));

// FIX 2026-07-25: immer mindestens 1 Item zurueckgeben (Platzhalter ohne vorgangKey/
// vorgangsnummer, wird von "Finde Blockade-Antwort" automatisch ignoriert), damit dieser
// Node zuverlaessig als "ausgefuehrt" gilt, wenn Matrix Nachrichten lesen direkt danach
// haengt - sonst race-abhaengiger 'Node hasnt been executed'-Fehler bei -Referenzen.
if (waiting.length === 0) {
  return [{ json: { _noBlockadesWaiting: true } }];
}

return waiting.map(item => ({ json: { ...item.json } }));

// Sucht in den zuletzt gelesenen Matrix-Nachrichten nach einer "<Code>-OK"
// oder "<Code>-SKIP"-Antwort auf eine dauerhaft blockierte Visual-Zeile
// (sharepicNeedStage topic_error/blocked_source_lock). "-OK" prueft die
// Zeile mit der IDENTISCHEN Logik wie "Filtere unbenachrichtigte Blockaden"
// in ALLRIS_P4_Content_Reaktion frisch gegen den aktuellen DB-Stand (kein
// Guard wird umgangen, nur neu bewertet) - bewusst dupliziert, gleiches
// Muster wie dort dokumentiert (Architekturpruefung 2026-07-22 F2/F9).
// "-SKIP" markiert dauerhaft "kein Sharepic noetig", Text-Content laeuft
// weiter. 2026-07-24 ergaenzt, siehe PROJECT_COORDINATION.md.
function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function safeBool(v) {
  if (v === true || v === 1) return true;
  if (typeof v === 'string') return v.trim().toLowerCase() === 'true';
  return false;
}
function parseObj(v) {
  if (!v) return {};
  if (typeof v === 'object' && !Array.isArray(v)) return v;
  try { const p = JSON.parse(String(v)); return (p && typeof p === 'object' && !Array.isArray(p)) ? p : {}; } catch (e) { return {}; }
}
function asArr(v) {
  if (Array.isArray(v)) return v.filter(Boolean).map(x => safeStr(x)).filter(Boolean);
  if (typeof v === 'string' && v.trim()) {
    try { const p = JSON.parse(v); if (Array.isArray(p)) return p.filter(Boolean).map(x => safeStr(x)).filter(Boolean); } catch (e) {}
    return v.split(/\s*\|\s*|\s*;\s*/).filter(Boolean).map(x => safeStr(x));
  }
  return [];
}
function num(v) {
  const n = parseFloat(safeStr(v).replace(',', '.'));
  return Number.isFinite(n) ? n : 0;
}
function norm(v) { return safeStr(v).toUpperCase(); }
function normText(v) {
  return safeStr(v).toLowerCase()
    .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
    .replace(/[„""'`´]/g, '').replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
}
function firstValue(...values) {
  for (const value of values) {
    if (value === null || value === undefined) continue;
    if (Array.isArray(value) && value.length > 0) return value;
    if (typeof value === 'object' && !Array.isArray(value) && Object.keys(value).length > 0) return value;
    if (safeStr(value) !== '') return value;
  }
  return '';
}

const SENSITIVE_CONTEXT_RE = /\b(minderjaehrig|minderjährig|kind|kinder|schueler|schüler|schuelerin|schülerin|behinder|barrierefrei|barrierefreiheit|blind|sehbehindert|taub|krank|pflege|rollstuhl|gefluecht|geflücht|wohnungslose|obdachlos|armut|opfer|notlage)\b/i;

function isSensitivePersonObject(v) {
  const n = normText(v);
  if (!n) return false;
  if (/\b(rollstuhlrampe|rampe|barrierefreier zugang|barrierefreier taster|taster|signalgeber|bodenplatte|bodenplatten|leitstreifen|lichtsignalanlage)\b/.test(n)) return false;
  return /\b(blinder|blinde|sehbehinderter|sehbehinderte|behinderter|behinderte|mensch mit behinderung|menschen mit behinderung|schueler|schuelerin|schüler|schülerin|kind|kinder|minderjaehriger|minderjährige|patient|patientin|pflegebeduerftiger|pflegebedürftige|rollstuhlfahrer|gefluechteter|geflüchtete|wohnungslose|obdachlose|kranker|kranke)\b/.test(n);
}
function isForbiddenSymbol(v, sourceNorm) {
  const n = normText(v);
  if (!n) return false;
  if (!/\b(waage|aktenberg|nebel|monster|hai|haie|marionette|marionetten|theaterbuehne|theaterbühne|theater|clown|clowns|maskottchen)\b/.test(n)) return false;
  if (sourceNorm.includes(n)) return false;
  // FIX (2026-07-27, Vorgang 2026/143 "Ungleichbehandlungen beim Denkmalschutz"): bisher musste
  // die GESAMTE normalisierte Phrase als zusammenhaengender Substring im Quelltext vorkommen, um
  // als "gegruendet" zu gelten. Das ist zu bruechig fuer KI-paraphrasierte Pflichtobjekte: "Fenster
  // im Rathaus" wurde faelschlich als Symbol-Drift geblockt, obwohl der Vorgang buchstaeblich von
  // genau diesen Fenstern handelt - der Quelltext sagt nur "Fenster im Dachgeschoss des ...
  // Nordwestfluegels des Rathauses", also dieselben Woerter, nicht direkt nebeneinander. Jetzt
  // stattdessen pruefen, ob JEDES eigenstaendige (nicht-triviale) Wort der Phrase einzeln im
  // Quelltext vorkommt - "Rathaus-Tuer" (kein einziges Vorkommen von "tuer" im Quelltext) bleibt
  // dadurch weiterhin zurecht blockiert, da dort tatsaechlich nie von einer Tuer die Rede ist.
  const STOPWORDS = new Set(['im','in','der','die','das','des','dem','den','und','am','an','auf','zum','zur','von','vom','fuer','bei','beim','ein','eine','einer','eines']);
  const words = n.split(' ').filter(w => w.length >= 3 && !STOPWORDS.has(w));
  if (words.length === 0) return true;
  return !words.every(w => sourceNorm.includes(w));
}
function hasSensitiveMetaphor(text, sensitive) {
  if (!sensitive) return false;
  const n = normText(text);
  if (/\bblind(e|er|es|en)?\s+(augen|sparschwein|haushalt|verwaltung|planung|politik|ampel|stadt)\b/.test(n)) return true;
  if (/\b(taub(e|er|es|en)?|lahm(e|er|es|en)?|krank(e|er|es|en)?|hilflos(e|er|es|en)?)\s+(verwaltung|planung|haushalt|politik|ampel|stadt)\b/.test(n)) return true;
  if (/barrierefreiheit.{0,30}\b(luxus|spass|spaß|teurer spass|teurer spaß)\b/.test(n)) return true;
  if (/\b(gefahrenszene|hilflosigkeit|panik|panisch|gefährdet|gefaehrdet|unfallopfer)\b/.test(n)) return true;
  return false;
}

function wouldStillBlock(j) {
  const oldStage = safeStr(j.sharepicNeedStage);
  if (!['topic_error', 'blocked_source_lock'].includes(oldStage)) return { blocked: false };

  const analysis = parseObj(j.analysisJson);
  const fakten = parseObj(j.faktenAgentJson);
  const visualAnchors = parseObj(analysis.visualAnchors);

  // Frisch aus faktenAgentJson ableiten (wie P4s kanonischer Node "Pruefe
  // Source-Lock (Content)"), NICHT das eingefrorene analysisJson.sourceLock
  // verwenden - das wird nur bei einem ERFOLGREICHEN P4-Lauf aktualisiert und
  // bleibt bei dauerhaft blockierten Zeilen auf dem Stand des letzten
  // (blockierten) Laufs stehen, auch wenn faktenAgentJson seither aktuellere
  // Daten enthaelt (2026-07-25, Vorgang 2026/138 als Realfall gefunden).
  const sourceLockErrors = [];
  if (!safeStr(fakten.sourceTopic)) sourceLockErrors.push('sourceTopic fehlt');
  if (asArr(fakten.requiredTerms).length < 2) sourceLockErrors.push('requiredTerms < 2');
  if (fakten.parseError === true) sourceLockErrors.push('faktenAgentJson.parseError ist true');
  if (sourceLockErrors.length > 0) return { blocked: true, reason: 'sourceLock unvollstaendig: ' + sourceLockErrors.join('; ') };
  const sourceLock = {
    sourceTopic: safeStr(fakten.sourceTopic),
    sourceConflict: safeStr(fakten.sourceConflict),
    requiredTerms: asArr(fakten.requiredTerms),
    requiredObjects: asArr(fakten.requiredObjects),
    requiredAction: safeStr(fakten.requiredAction),
    affectedGroups: asArr(fakten.affectedGroups)
  };

  const sprengstoff = norm(firstValue(j.sprengstoff, analysis.sprengstoff));
  const empfehlung = norm(firstValue(j.empfehlung, analysis.empfehlung));
  const relevantScore = num(firstValue(j.relevantScore, analysis.relevantScore, analysis.relevanz));
  const kommunikationspotenzial = num(firstValue(j.kommunikationspotenzial, analysis.kommunikationspotenzial));
  const instagramCarouselNoetig = safeBool(j.instagramCarouselNoetig) || safeBool(analysis.instagramCarouselNoetig);
  const instagramSharepicAngefragt = safeBool(j.instagramSharepicNoetig) || safeBool(analysis.instagramSharepicNoetig);

  const visualRequested = instagramCarouselNoetig || instagramSharepicAngefragt ||
    (empfehlung === 'REAGIEREN' && ['MITTEL', 'HOCH'].includes(sprengstoff)) ||
    relevantScore >= 8 || kommunikationspotenzial >= 8;

  if (!visualRequested) return { blocked: false };

  const anchorErrors = [];
  if (!safeStr(visualAnchors.satireThemaKonkret)) anchorErrors.push('satireThemaKonkret fehlt');
  if (!safeStr(visualAnchors.satireKonfliktKonkret)) anchorErrors.push('satireKonfliktKonkret fehlt');
  if (asArr(visualAnchors.visualPflichtobjekte).length < 2) anchorErrors.push('visualPflichtobjekte < 2');
  if (!safeStr(visualAnchors.visualPflichthandlung)) anchorErrors.push('visualPflichthandlung fehlt');
  if (!safeStr(visualAnchors.visualErkennungssatz)) anchorErrors.push('visualErkennungssatz fehlt');
  if (!safeStr(visualAnchors.visualUeberzeichnung)) anchorErrors.push('visualUeberzeichnung fehlt');
  if (asArr(visualAnchors.visualVerboteneErsatzmotive).length < 2) anchorErrors.push('visualVerboteneErsatzmotive < 2');
  // Wie bei sourceLock (siehe Kommentar oben): NICHT das eingefrorene analysisJson.visualAnchorsValid
  // pruefen, sondern die 7 einzelnen visualAnchors-Felder oben sind bereits die frische Neuableitung
  // (identische Vollstaendigkeitspruefung wie in P3_Bewertungs "Parse Analyse JSON"). Das gefrorene
  // Flag stammt vom letzten (moeglicherweise blockierten) Lauf und kann veraltet sein, auch wenn die
  // Felder selbst laengst vollstaendig sind (2026-07-25, Vorgang 2026/109-01 als Realfall gefunden).
  if (anchorErrors.length > 0) return { blocked: true, reason: 'VisualAnchors unvollstaendig: ' + anchorErrors.join('; ') };

  const sourceStrictText = [j.title, j.vorgangsnummer, j.summaryText, j.combinedText].map(safeStr).join('\n');
  const sourceNorm = normText(sourceStrictText);
  const sensitiveContext = SENSITIVE_CONTEXT_RE.test(normText(sourceStrictText + ' ' + asArr(sourceLock.affectedGroups).join(' ')));

  const sensitiveObjectsFound = sensitiveContext ? [
    ...asArr(visualAnchors.visualPflichtobjekte).filter(isSensitivePersonObject),
    ...asArr(sourceLock.requiredObjects).filter(isSensitivePersonObject)
  ] : [];
  const forbiddenSymbolsFound = [
    ...asArr(visualAnchors.visualPflichtobjekte).filter(v => isForbiddenSymbol(v, sourceNorm)),
    ...asArr(sourceLock.requiredObjects).filter(v => isForbiddenSymbol(v, sourceNorm))
  ];
  const visualText = [
    visualAnchors.visualUeberzeichnung, visualAnchors.visualErkennungssatz, analysis.visualMetaphor,
    analysis.satireBrief, analysis.satireAngle, asArr(analysis.satirePunchlines).join(' '),
    analysis.moeglicheSatirischeReaktion
  ].map(safeStr).join(' ');

  if (sensitiveObjectsFound.length > 0) return { blocked: true, reason: 'Guard blockiert: Sensible Betroffene als Pflichtobjekt/sourceLock.requiredObject erkannt: ' + sensitiveObjectsFound.join(', ') };
  if (forbiddenSymbolsFound.length > 0) return { blocked: true, reason: 'Guard blockiert: Symbol-Drift als Pflichtobjekt/sourceLock.requiredObject erkannt: ' + forbiddenSymbolsFound.join(', ') };
  if (hasSensitiveMetaphor(visualText, sensitiveContext)) return { blocked: true, reason: 'Guard blockiert: sensible Metapher in Visual-/Satirefeldern erkannt' };
  return { blocked: false };
}

function vnCode(v) { return safeStr(v).replace(/[^0-9A-Za-z]+/g, '-').replace(/^-+|-+$/g, ''); }
function normCode(v) { return safeStr(v).toLowerCase().replace(/^#/, '').replace(/\s+/g, ''); }

const waitingRows = $('Finde wartende Blockaden').all().map(i => i.json || {});
const byCode = new Map();
for (const row of waitingRows) {
  const code = normCode(vnCode(row.vorgangsnummer) || vnCode(row.vorgangKey));
  if (code) byCode.set(code, row);
}

const chunk = Array.isArray(items[0].json.chunk) ? items[0].json.chunk : [];
const matches = [];
// FIX 2026-07-25: unerkannte Codes (Tippfehler, bereits erledigter Vorgang, falsche
// Vorgangsnummer) wurden bisher komplett stillschweigend ignoriert - der Nutzer wusste nie,
// ob seine Antwort ueberhaupt gelesen wurde. Jetzt zumindest eine Rueckmeldung, wenn eine
// Nachricht wie ein -OK/-SKIP-Code aussieht, aber zu keiner aktuell offenen Blockade passt.
const unmatched = [];
for (const ev of chunk) {
  if (!ev || ev.type !== 'm.room.message') continue;
  const content = ev.content || {};
  if (content.msgtype !== 'm.text') continue;
  const ts = Number(ev.origin_server_ts || 0);
  const replyNorm = normCode(content.body);
  if (!replyNorm) continue;

  let action = null, code = null;
  if (replyNorm.endsWith('-ok')) { action = 'ok'; code = replyNorm.slice(0, -3); }
  else if (replyNorm.endsWith('-skip')) { action = 'skip'; code = replyNorm.slice(0, -5); }
  if (!action) continue;

  const row = byCode.get(code);
  if (!row) { unmatched.push({ ts, action, code }); continue; }
  matches.push({ ts, action, row });
}

if (matches.length === 0) {
  if (unmatched.length === 0) return [];
  unmatched.sort((a, b) => a.ts - b.ts);
  const missed = unmatched[0];
  return [{
    json: {
      _skipWrite: true,
      _matrixAction: 'block_reply_no_match',
      _confirmMessage: '⚠️ "' + missed.code + '-' + missed.action.toUpperCase() + '" passt zu keiner aktuell offenen Blockade. Möglich: Vorgangsnummer falsch/vertippt, oder die Zeile ist inzwischen aus einem anderen Grund nicht mehr in der Blockaden-Warteliste.',
      _confirmTxnId: 'blk_confirm_nomatch_' + safeStr(missed.code).replace(/[^a-zA-Z0-9]/g, '') + '_' + Date.now()
    }
  }];
}

matches.sort((a, b) => a.ts - b.ts);
const chosen = matches[0];
const vorgangKeySafe = safeStr(chosen.row.vorgangKey).replace(/[^a-zA-Z0-9]/g, '');

if (chosen.action === 'skip') {
  return [{
    json: {
      ...chosen.row,
      sharepicNeedStage: 'not_applicable',
      visualPromptStage: '',
      visualDecisionReason: 'Manuell per Matrix (-SKIP) als "kein Sharepic" markiert',
      imagePrompt: '', imageHeadline: '', imageSubline: '', imageNegativePrompt: '', visualJson: '{}',
      imageStage: safeStr(chosen.row.imageFinalPath) ? 'composed' : 'not_started',
      _skipWrite: false,
      _matrixAction: 'block_skip',
      _confirmMessage: '☑️ Ok, für ' + safeStr(chosen.row.vorgangsnummer) + ' - ' + safeStr(chosen.row.title) + ' wird dauerhaft kein Sharepic erzeugt. Text-Content läuft normal weiter.',
      _confirmTxnId: 'blk_confirm_' + vorgangKeySafe + '_skip_' + Date.now()
    }
  }];
}

// action === 'ok': frisch pruefen, kein Guard wird umgangen
const result = wouldStillBlock(chosen.row);
if (result.blocked) {
  return [{
    json: {
      ...chosen.row,
      _skipWrite: true,
      _matrixAction: 'block_recheck_still_blocked',
      _confirmMessage: '⛔ ' + safeStr(chosen.row.vorgangsnummer) + ' - ' + safeStr(chosen.row.title) + ' ist immer noch blockiert. Grund: ' + result.reason,
      _confirmTxnId: 'blk_confirm_' + vorgangKeySafe + '_stillblocked_' + Date.now()
    }
  }];
}

const okAnalysis = parseObj(chosen.row.analysisJson);
const okFakten = parseObj(chosen.row.faktenAgentJson);
const okSourceLock = {
  sourceTopic: safeStr(okFakten.sourceTopic),
  sourceConflict: safeStr(okFakten.sourceConflict),
  requiredTerms: asArr(okFakten.requiredTerms),
  requiredObjects: asArr(okFakten.requiredObjects),
  requiredAction: safeStr(okFakten.requiredAction),
  affectedGroups: asArr(okFakten.affectedGroups)
};
const okAnalysisJson = JSON.stringify({ ...okAnalysis, sourceLock: okSourceLock, sourceLockValid: true });

return [{
  json: {
    ...chosen.row,
    analysisJson: okAnalysisJson,
    sharepicNeedStage: 'topic_ok',
    visualPromptStage: 'needs_prompt',
    visualDecisionReason: 'Manuell per Matrix (-OK) erneut geprueft: nicht mehr blockiert',
    imagePrompt: '', imageHeadline: '', imageSubline: '', imageNegativePrompt: '', visualJson: '{}',
    imageStage: safeStr(chosen.row.imageFinalPath) ? 'composed' : 'not_started',
    _skipWrite: false,
    _matrixAction: 'block_recheck_ok',
    _confirmMessage: '✅ ' + safeStr(chosen.row.vorgangsnummer) + ' - ' + safeStr(chosen.row.title) + ' ist nicht mehr blockiert und wird jetzt fuer den Bild-Prompt freigegeben.',
    _confirmTxnId: 'blk_confirm_' + vorgangKeySafe + '_recheckok_' + Date.now()
  }
}];

// FIX 2026-08-01 (Nutzerwunsch): zeichnet die tatsaechliche menschliche Entscheidung
// (nicht nur das automatisierte QA-Agent-Verdikt) als Lernbeispiel auf. qaStage='headline_choice'
// haelt diese Beispiele getrennt von den QA-Agent-Beispielen (qaStage='analyse'), damit spaeter
// gezielt danach gefiltert werden kann (siehe P3e "Lern-Agent: Hole Kopfzeilen-Beispiele").
function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function parseArr(v) {
  if (Array.isArray(v)) return v;
  try { const p = JSON.parse(String(v || '[]')); return Array.isArray(p) ? p : []; } catch (e) { return []; }
}

const row = $json;
const candidates = parseArr(row._learnAllCandidates);
const chosenCode = safeStr(row._learnChosenCode);
const isReroll = row._matrixAction === 'reroll';

const candidateLines = candidates.map(c => safeStr(c.code) + ': ' + safeStr(c.imageHeadline) + ' - ' + safeStr(c.imageSubline));

let exampleSummary;
if (isReroll) {
  exampleSummary = safeStr(row.title) + ' - Nutzer hat ALLE ' + candidates.length + ' Kandidaten abgelehnt (Reroll angefordert). Angebotene Varianten:\n' + candidateLines.join('\n');
} else {
  const chosen = candidates.find(c => safeStr(c.code) === chosenCode) || {};
  exampleSummary = safeStr(row.title) + ' - Nutzer waehlte ' + chosenCode + ': "' + safeStr(chosen.imageHeadline) + '" - "' + safeStr(chosen.imageSubline) + '". Alle angebotenen Varianten:\n' + candidateLines.join('\n');
}

return {
  json: {
    lernAction: 'record',
    vorgangKey: safeStr(row.vorgangKey),
    vorgangsnummer: safeStr(row.vorgangsnummer),
    qaStage: 'headline_choice',
    source: 'human_headline_choice',
    outcome: isReroll ? 'all_rejected' : 'selected',
    exampleSummary: exampleSummary.slice(0, 2000),
    detailsJson: JSON.stringify({ chosenCode, candidates })
  }
};

// Filtert auf ALLE Zeilen, die auf eine Headline/Subline-Auswahl per Matrix
// warten (koennen mehrere gleichzeitig sein - die Vorgangsnummer ist seit
// V2 Teil des Codes, deshalb keine Mehrdeutigkeit mehr bei parallelen Wartern),
// und liest je Zeile die Kandidaten sowie den Zeitstempel des Matrix-Posts aus
// visualJson.headlineCandidates / visualJson.candidatesPostedAt.
function parseObj(v) {
  if (!v) return {};
  if (typeof v === 'object' && !Array.isArray(v)) return v;
  try {
    const p = JSON.parse(String(v));
    return (p && typeof p === 'object' && !Array.isArray(p)) ? p : {};
  } catch (e) {
    return {};
  }
}

const waiting = items.filter(item => String(item.json.headlineChoiceStage || '').trim() === 'awaiting_headline_choice');

// FIX 2026-07-25: immer mindestens 1 Item zurueckgeben (Platzhalter ohne vorgangKey,
// wird von "Finde erinnerungsfällige Vorgänge" automatisch uebersprungen und von
// "Finde Sat-Antwort" ueber $()-Referenz separat gelesen), damit dieser Node
// zuverlaessig als "ausgefuehrt" gilt, wenn Matrix Nachrichten lesen ueber den
// Merge-Knoten darauf wartet - sonst race-abhaengiger 'Node hasnt been executed'-Fehler.
if (waiting.length === 0) {
  return [{ json: { _noHeadlinesWaiting: true } }];
}

return waiting.map(item => {
  const row = item.json;
  const vj = parseObj(row.visualJson);
  const candidates = Array.isArray(vj.headlineCandidates) ? vj.headlineCandidates : [];
  const candidatesPostedAt = vj.candidatesPostedAt || null;
  const lastReminderAt = vj.lastReminderAt || null;
  const reminderCount = Number(vj.reminderCount || 0);
  // FIX 2026-08-01: kernbotschaft mit durchreichen, damit "Finde erinnerungsfaellige
  // Vorgaenge" eine Erinnerung mit demselben Kontext bauen kann wie die urspruengliche
  // Umfrage in P3e (die hatte Kernbotschaft + satireBrief/groundingHintText pro Kandidat,
  // die Erinnerung bisher nur die nackte Code:Headline-Subline-Zeile).
  const kernbotschaft = vj.kernbotschaft || '';
  return {
    json: {
      ...row,
      _headlineCandidates: candidates,
      _candidatesPostedAt: candidatesPostedAt,
      _lastReminderAt: lastReminderAt,
      _reminderCount: reminderCount,
      _kernbotschaft: kernbotschaft
    }
  };
});

// Sucht in den zuletzt gelesenen Matrix-Nachrichten nach einer Antwort, die
// exakt (bis auf optionales '#' und Leerzeichen) einem Kandidaten-Code
// entspricht - der Code enthaelt seit V2 die Vorgangsnummer
// (z.B. "2026-192-K2"), deshalb ist die Zuordnung eindeutig, auch wenn
// mehrere Vorgaenge gleichzeitig auf eine Auswahl warten.
// Die blosse Vorgangsnummer mit "-X"-Suffix (z.B. "2026-192-X", OHNE Kandidat)
// ist kein Auswahl-, sondern ein Reroll-Wunsch fuer den GANZEN Vorgang: statt
// der Kandidaten wird er auf visualPromptStage='needs_prompt' zurueckgesetzt
// (imageHeadline/imageSubline geleert), damit P2 beim naechsten planmaessigen
// Lauf komplett neue Headline/Subline-Varianten erzeugt (siehe ZIEL_STATUS in
// "Filtere Visual-Status"). Welcher der vier Kandidaten dabei angegeben wird,
// spielt keine Rolle - deshalb wird fuer den Reroll nur die Vorgangsnummer
// gematcht, kein einzelner Kandidaten-Code.
// Findet sich keine gültige, neue Antwort, endet der Lauf ohne Änderung -
// der nächste Poll (alle 15 Min) versucht es erneut.
function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function normCode(v) { return safeStr(v).toLowerCase().replace(/^#/, '').replace(/\s+/g, ''); }
function vnCodeOf(row) { return safeStr(row.vorgangsnummer).replace(/[^0-9A-Za-z]+/g, '-').replace(/^-+|-+$/g, ''); }

const waitingRows = $('Finde wartenden Vorgang').all().map(i => i.json || {});

// Kandidaten-Ebene (fuer normale Auswahl) und Vorgangs-Ebene (fuer Reroll),
// je mit eigener candidatesPostedAt-Grenze (eine Antwort zaehlt nur, wenn sie
// NACH dem Posten der Kandidaten fuer genau diesen Vorgang kam).
const allCandidates = [];
const allRows = [];
for (const row of waitingRows) {
  const candidates = Array.isArray(row._headlineCandidates) ? row._headlineCandidates : [];
  const postedAtMs = row._candidatesPostedAt ? Date.parse(row._candidatesPostedAt) : 0;
  for (const c of candidates) {
    allCandidates.push({ row, candidate: c, postedAtMs, normCode: normCode(c.code) });
  }
  if (candidates.length > 0) {
    allRows.push({ row, postedAtMs, normVnCode: normCode(vnCodeOf(row)) });
  }
}

const chunk = Array.isArray(items[0].json.chunk) ? items[0].json.chunk : [];

const matches = [];
for (const ev of chunk) {
  if (!ev || ev.type !== 'm.room.message') continue;
  const content = ev.content || {};
  if (content.msgtype !== 'm.text') continue;
  const ts = Number(ev.origin_server_ts || 0);
  let replyNorm = normCode(content.body);
  if (!replyNorm) continue;

  let isRerollRequest = false;
  if (replyNorm.endsWith('-x')) {
    isRerollRequest = true;
    replyNorm = replyNorm.slice(0, -2);
  }

  if (isRerollRequest) {
    for (const entry of allRows) {
      if (entry.postedAtMs && ts <= entry.postedAtMs) continue;
      if (entry.normVnCode === replyNorm) {
        matches.push({ ts, isRerollRequest: true, row: entry.row });
      }
    }
  } else {
    for (const entry of allCandidates) {
      if (entry.postedAtMs && ts <= entry.postedAtMs) continue;
      if (entry.normCode === replyNorm) {
        matches.push({ ts, isRerollRequest: false, row: entry.row, candidate: entry.candidate });
      }
    }
  }
}

if (matches.length === 0) {
  return [];
}

// FIX 2026-07-25 (Nutzerwunsch): bisher wurde je Durchlauf nur die AELTESTE gueltige Antwort
// verarbeitet (matches[0]) - bei mehreren gleichzeitig wartenden Umfragen kam pro Lauf nur eine
// einzige Bestaetigung zurueck, der Rest blieb bis zu den naechsten Laeufen stumm in der
// Warteschlange. Das sah wie ein Fehler aus, obwohl die Nachrichten korrekt gelesen wurden.
// Jetzt werden ALLE im Fenster gefundenen gueltigen Antworten in diesem einen Durchlauf
// verarbeitet - bei mehreren Antworten fuer DENSELBEN Vorgang gewinnt weiterhin die aelteste
// (z.B. wenn jemand zweimal geantwortet hat), aber unterschiedliche Vorgaenge laufen jetzt
// parallel durch, jeder bekommt sofort seine eigene Bestaetigung.
matches.sort((a, b) => a.ts - b.ts);
const chosenByVorgang = new Map();
for (const m of matches) {
  const vk = safeStr(m.row.vorgangKey);
  if (!vk || chosenByVorgang.has(vk)) continue; // aelteste Antwort pro Vorgang gewinnt (matches ist bereits nach ts sortiert)
  chosenByVorgang.set(vk, m);
}

function safeArr(v) { return Array.isArray(v) ? v : []; }

const out = [];
for (const chosen of chosenByVorgang.values()) {
  const vorgangKeySafe = safeStr(chosen.row.vorgangKey).replace(/[^a-zA-Z0-9]/g, '');

  if (chosen.isRerollRequest) {
    out.push({
      json: {
        ...chosen.row,
        imageHeadline: '',
        imageSubline: '',
        headlineChoiceStage: 'needs_kernbotschaft',
        visualPromptStage: '',
        imageStage: safeStr(chosen.row.imageFinalPath) ? 'composed' : 'not_started',
        _matrixAction: 'reroll',
        _confirmMessage: '🔄 Ok, für ' + safeStr(chosen.row.vorgangsnummer) + ' - ' + safeStr(chosen.row.title) + ' finde ich eine komplett neue Kernbotschaft. Das dauert bis zum nächsten planmäßigen Durchlauf. Es wird weiterhin nichts veröffentlicht, bis du eine Formulierung bestätigst.',
        _confirmTxnId: 'hdl_confirm_' + vorgangKeySafe + '_reroll_' + Date.now(),
        // FIX 2026-08-01 (Nutzerwunsch "Lernagent soll von meinen Entscheidungen lernen"):
        // Kandidatenliste durchreichen, damit ein nachgelagerter Schritt einen Lernbeispiel-
        // Eintrag bauen kann (hier: Reroll = alle angebotenen Kandidaten abgelehnt).
        _learnAllCandidates: JSON.stringify(safeArr(chosen.row._headlineCandidates)),
        _learnChosenCode: ''
      }
    });
    continue;
  }

  // Cutover 2026-07-18: Kandidaten tragen jetzt das volle Satire-Agent-Varianten-Feld-Set
  // (nicht mehr nur imageHeadline/imageSubline aus P5s alter Headline-Generierung). Die
  // gewaehlte Variante ueberschreibt die kompletten satire*-Spalten, damit Bild-Agent (P5) mit
  // genau der Variante arbeitet, die der Mensch fuers Bild ausgewaehlt hat - unabhaengig davon,
  // welche Variante P3 automatisch fuer den Text gewaehlt hatte.
  out.push({
    json: {
      ...chosen.row,
      imageHeadline: safeStr(chosen.candidate.imageHeadline),
      imageSubline: safeStr(chosen.candidate.imageSubline),
      satireBrief: safeStr(chosen.candidate.satireBrief),
      satireAngle: safeStr(chosen.candidate.satireAngle),
      satirePunchlines: JSON.stringify(safeArr(chosen.candidate.satirePunchlines)),
      satireTarget: safeStr(chosen.candidate.satireTarget),
      satireIntensity: Number(chosen.candidate.satireIntensity) || 0,
      satireDoNotClaim: JSON.stringify(safeArr(chosen.candidate.satireDoNotClaim)),
      satireSafetyNote: safeStr(chosen.candidate.satireSafetyNote),
      headlineChoiceStage: 'headline_selected',
      contentStage: 'needs_content',
      imageStage: safeStr(chosen.row.imageFinalPath) ? 'composed' : 'not_started',
      _matrixAction: 'select',
      _confirmMessage: '✅ Danke! Für ' + safeStr(chosen.row.vorgangsnummer) + ' - ' + safeStr(chosen.row.title) + ' wurde übernommen: "' + safeStr(chosen.candidate.imageHeadline) + '" - "' + safeStr(chosen.candidate.imageSubline) + '". Text und Bild werden jetzt freigegeben und beim nächsten planmäßigen Durchlauf veröffentlicht.',
      _confirmTxnId: 'hdl_confirm_' + vorgangKeySafe + '_select_' + normCode(safeStr(chosen.candidate.code)) + '_' + Date.now(),
      // FIX 2026-08-01 (Nutzerwunsch "Lernagent soll von meinen Entscheidungen lernen"):
      // volle Kandidatenliste + gewaehlter Code durchreichen, damit ein nachgelagerter Schritt
      // die tatsaechliche menschliche Entscheidung als Lernbeispiel speichern kann.
      _learnAllCandidates: JSON.stringify(safeArr(chosen.row._headlineCandidates)),
      _learnChosenCode: safeStr(chosen.candidate.code)
    }
  });
}

return out;

// Prueft, welche wartenden Vorgaenge laenger als REMINDER_INTERVAL_MS keine
// neue Nachricht bekommen haben, und baut dafuer eine Erinnerung mit den
// bereits bestehenden Kandidaten (keine neue KI-Generierung, kein neuer Text).
// Stoppt nach MAX_REMINDERS, damit ein unbeantworteter Vorgang nicht endlos nervt.
//
// FIX (Architekturpruefung 2026-07-22, Befund F3): bisher wurde ein Vorgang nach
// Erreichen von MAX_REMINDERS stillschweigend uebersprungen - unsichtbar in der
// Status-Uebersicht, ohne jede Markierung. Jetzt wird EINMALIG (nicht bei jedem
// 15-Minuten-Lauf erneut) ein sichtbarer Hinweis in visualJson.workflow
// hinterlegt (reminderExhausted/reminderExhaustedAt) - keine neue DB-Spalte
// noetig, da visualJson bereits existiert und bereits von diesem Workflow
// geschrieben wird. headlineChoiceStage bleibt dabei bewusst unveraendert:
// der Mensch kann jederzeit trotzdem noch per Matrix antworten, es werden nur
// keine weiteren automatischen Erinnerungen mehr verschickt.
const REMINDER_INTERVAL_MS = 12 * 60 * 60 * 1000;
const MAX_REMINDERS = 5;

function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function parseObj(v) {
  if (!v) return {};
  if (typeof v === 'object' && !Array.isArray(v)) return v;
  try { const p = JSON.parse(String(v)); return (p && typeof p === 'object' && !Array.isArray(p)) ? p : {}; }
  catch (e) { return {}; }
}

const now = Date.now();
const due = [];

for (const item of items) {
  const row = item.json;
  const reminderCount = Number(row._reminderCount || 0);

  if (reminderCount >= MAX_REMINDERS) {
    const vj = parseObj(row.visualJson);
    const alreadyMarkedExhausted = !!(vj.workflow && vj.workflow.reminderExhausted === true);
    if (alreadyMarkedExhausted) continue;

    vj.workflow = {
      ...(vj.workflow && typeof vj.workflow === 'object' && !Array.isArray(vj.workflow) ? vj.workflow : {}),
      reminderExhausted: true,
      reminderExhaustedAt: new Date().toISOString()
    };

    due.push({
      json: {
        ...row,
        visualJson: JSON.stringify(vj),
        _reminderExhaustedOnly: true
      }
    });
    continue;
  }

  const lastPromptMs = row._lastReminderAt
    ? Date.parse(row._lastReminderAt)
    : (row._candidatesPostedAt ? Date.parse(row._candidatesPostedAt) : 0);
  if (!lastPromptMs || (now - lastPromptMs) < REMINDER_INTERVAL_MS) continue;

  const candidates = Array.isArray(row._headlineCandidates) ? row._headlineCandidates : [];
  if (candidates.length === 0) continue;

  const nextReminderCount = reminderCount + 1;
  // FIX 2026-08-01: Erinnerung war deutlich knapper als die urspruengliche Umfrage in P3e
  // (nur Code:Headline-Subline, ohne Kernbotschaft-Kontext und ohne satireBrief/
  // groundingHintText pro Kandidat) - nicht absichtlich, siehe Kommentar oben ("keine neue
  // KI-Generierung, kein neuer Text" meinte nur keinen neuen Kandidaten-Text, nicht weniger
  // Kontext). Jetzt an dasselbe Format wie die Original-Umfrage angeglichen.
  const kernbotschaft = safeStr(row._kernbotschaft);
  const lines = [
    '⏰ Erinnerung (' + nextReminderCount + '/' + MAX_REMINDERS + ') - noch offen: ' + safeStr(row.vorgangsnummer) + ' - ' + safeStr(row.title),
    ''
  ];
  if (kernbotschaft) {
    lines.push(kernbotschaft, '');
  }
  lines.push('🎨 Formulierungen zur Auswahl:', '');
  for (const c of candidates) {
    lines.push(safeStr(c.code) + ': ' + safeStr(c.imageHeadline) + ' - ' + safeStr(c.imageSubline));
    if (c.satireBrief) lines.push('   ' + safeStr(c.satireBrief));
    if (c.groundingHintText) lines.push('   ' + safeStr(c.groundingHintText));
  }
  lines.push('');
  const exampleCode = candidates.length > 0 ? safeStr(candidates[0].code) : '';
  const vnCode = safeStr(row.vorgangsnummer).replace(/[^0-9A-Za-z]+/g, '-').replace(/^-+|-+$/g, '');
  lines.push('Antworte mit dem gewuenschten Code (z.B. ' + exampleCode + '), um die Auswahl zu bestaetigen, oder mit \'' + vnCode + '-X\' fuer komplett neue Vorschlaege (Vorgangsnummer + -X, ohne Kandidat).');

  const vorgangKeySafe = safeStr(row.vorgangKey).replace(/[^a-zA-Z0-9]/g, '');
  const txnId = 'hdl_remind_' + vorgangKeySafe + '_r' + nextReminderCount;

  due.push({
    json: {
      ...row,
      matrixReminderMessage: lines.join('\n'),
      matrixReminderTxnId: txnId,
      _nextReminderCount: nextReminderCount,
      _reminderExhaustedOnly: false
    }
  });
}

return due;

// Stellt den Vorgangskontext nach dem Matrix-Versand wieder her (gleiches Muster
// wie "Stelle Kontext nach Matrix wieder her" in P2) - der HTTP-Node ersetzt das
// Item-JSON durch die rohe Matrix-API-Antwort und wuerde sonst vorgangKey,
// reminderCount usw. verlieren, sodass "Speichere Erinnerung" keine Zeile findet.
function parseObj(v) {
  if (!v) return {};
  if (typeof v === 'object' && !Array.isArray(v)) return v;
  try { const p = JSON.parse(String(v)); return (p && typeof p === 'object' && !Array.isArray(p)) ? p : {}; } catch (e) { return {}; }
}

const response = $input.item.json || {};
const base = $('Finde erinnerungsfällige Vorgänge').item.json || {};

const hasError = !!(
  response.error ||
  response.errcode ||
  (response.statusCode && Number(response.statusCode) >= 400)
);
const eventId = response.event_id || response.eventId || '';

const existingVisual = parseObj(base.visualJson);

return {
  json: {
    ...base,
    visualJson: JSON.stringify({
      ...existingVisual,
      lastReminderAt: hasError ? (base._lastReminderAt || existingVisual.candidatesPostedAt || null) : new Date().toISOString(),
      reminderCount: hasError ? Number(base._reminderCount || 0) : base._nextReminderCount
    }),
    matrixReminderSentOk: !hasError && !!eventId,
    matrixReminderError: hasError ? (response.error || response.errcode || 'Matrix-Versand fehlgeschlagen') : ''
  }
};

// Filtert auf ALLE Zeilen, die dauerhaft blockiert sind (sharepicNeedStage
// topic_error oder blocked_source_lock) und per Matrix-Antwort geklaert
// werden koennen (2026-07-24 ergaenzt, siehe PROJECT_COORDINATION.md).
function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }

const waiting = items.filter(item => ['topic_error', 'blocked_source_lock'].includes(safeStr(item.json.sharepicNeedStage)));

// FIX 2026-07-25: immer mindestens 1 Item zurueckgeben (Platzhalter ohne vorgangKey/
// vorgangsnummer, wird von "Finde Blockade-Antwort" automatisch ignoriert), damit dieser
// Node zuverlaessig als "ausgefuehrt" gilt, wenn Matrix Nachrichten lesen direkt danach
// haengt - sonst race-abhaengiger 'Node hasnt been executed'-Fehler bei -Referenzen.
if (waiting.length === 0) {
  return [{ json: { _noBlockadesWaiting: true } }];
}

return waiting.map(item => ({ json: { ...item.json } }));

// Sucht in den zuletzt gelesenen Matrix-Nachrichten nach einer "<Code>-OK"
// oder "<Code>-SKIP"-Antwort auf eine dauerhaft blockierte Visual-Zeile
// (sharepicNeedStage topic_error/blocked_source_lock). "-OK" prueft die
// Zeile mit der IDENTISCHEN Logik wie "Filtere unbenachrichtigte Blockaden"
// in ALLRIS_P4_Content_Reaktion frisch gegen den aktuellen DB-Stand (kein
// Guard wird umgangen, nur neu bewertet) - bewusst dupliziert, gleiches
// Muster wie dort dokumentiert (Architekturpruefung 2026-07-22 F2/F9).
// "-SKIP" markiert dauerhaft "kein Sharepic noetig", Text-Content laeuft
// weiter. 2026-07-24 ergaenzt, siehe PROJECT_COORDINATION.md.
function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function safeBool(v) {
  if (v === true || v === 1) return true;
  if (typeof v === 'string') return v.trim().toLowerCase() === 'true';
  return false;
}
function parseObj(v) {
  if (!v) return {};
  if (typeof v === 'object' && !Array.isArray(v)) return v;
  try { const p = JSON.parse(String(v)); return (p && typeof p === 'object' && !Array.isArray(p)) ? p : {}; } catch (e) { return {}; }
}
function asArr(v) {
  if (Array.isArray(v)) return v.filter(Boolean).map(x => safeStr(x)).filter(Boolean);
  if (typeof v === 'string' && v.trim()) {
    try { const p = JSON.parse(v); if (Array.isArray(p)) return p.filter(Boolean).map(x => safeStr(x)).filter(Boolean); } catch (e) {}
    return v.split(/\s*\|\s*|\s*;\s*/).filter(Boolean).map(x => safeStr(x));
  }
  return [];
}
function num(v) {
  const n = parseFloat(safeStr(v).replace(',', '.'));
  return Number.isFinite(n) ? n : 0;
}
function norm(v) { return safeStr(v).toUpperCase(); }
function normText(v) {
  return safeStr(v).toLowerCase()
    .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
    .replace(/[„""'`´]/g, '').replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
}
function firstValue(...values) {
  for (const value of values) {
    if (value === null || value === undefined) continue;
    if (Array.isArray(value) && value.length > 0) return value;
    if (typeof value === 'object' && !Array.isArray(value) && Object.keys(value).length > 0) return value;
    if (safeStr(value) !== '') return value;
  }
  return '';
}

const SENSITIVE_CONTEXT_RE = /\b(minderjaehrig|minderjährig|kind|kinder|schueler|schüler|schuelerin|schülerin|behinder|barrierefrei|barrierefreiheit|blind|sehbehindert|taub|krank|pflege|rollstuhl|gefluecht|geflücht|wohnungslose|obdachlos|armut|opfer|notlage)\b/i;

function isSensitivePersonObject(v) {
  const n = normText(v);
  if (!n) return false;
  if (/\b(rollstuhlrampe|rampe|barrierefreier zugang|barrierefreier taster|taster|signalgeber|bodenplatte|bodenplatten|leitstreifen|lichtsignalanlage)\b/.test(n)) return false;
  return /\b(blinder|blinde|sehbehinderter|sehbehinderte|behinderter|behinderte|mensch mit behinderung|menschen mit behinderung|schueler|schuelerin|schüler|schülerin|kind|kinder|minderjaehriger|minderjährige|patient|patientin|pflegebeduerftiger|pflegebedürftige|rollstuhlfahrer|gefluechteter|geflüchtete|wohnungslose|obdachlose|kranker|kranke)\b/.test(n);
}
function isForbiddenSymbol(v, sourceNorm) {
  const n = normText(v);
  if (!n) return false;
  if (!/\b(waage|aktenberg|nebel|monster|hai|haie|marionette|marionetten|theaterbuehne|theaterbühne|theater|clown|clowns|maskottchen)\b/.test(n)) return false;
  if (sourceNorm.includes(n)) return false;
  // FIX (2026-07-27, Vorgang 2026/143 "Ungleichbehandlungen beim Denkmalschutz"): bisher musste
  // die GESAMTE normalisierte Phrase als zusammenhaengender Substring im Quelltext vorkommen, um
  // als "gegruendet" zu gelten. Das ist zu bruechig fuer KI-paraphrasierte Pflichtobjekte: "Fenster
  // im Rathaus" wurde faelschlich als Symbol-Drift geblockt, obwohl der Vorgang buchstaeblich von
  // genau diesen Fenstern handelt - der Quelltext sagt nur "Fenster im Dachgeschoss des ...
  // Nordwestfluegels des Rathauses", also dieselben Woerter, nicht direkt nebeneinander. Jetzt
  // stattdessen pruefen, ob JEDES eigenstaendige (nicht-triviale) Wort der Phrase einzeln im
  // Quelltext vorkommt - "Rathaus-Tuer" (kein einziges Vorkommen von "tuer" im Quelltext) bleibt
  // dadurch weiterhin zurecht blockiert, da dort tatsaechlich nie von einer Tuer die Rede ist.
  const STOPWORDS = new Set(['im','in','der','die','das','des','dem','den','und','am','an','auf','zum','zur','von','vom','fuer','bei','beim','ein','eine','einer','eines']);
  const words = n.split(' ').filter(w => w.length >= 3 && !STOPWORDS.has(w));
  if (words.length === 0) return true;
  return !words.every(w => sourceNorm.includes(w));
}
function hasSensitiveMetaphor(text, sensitive) {
  if (!sensitive) return false;
  const n = normText(text);
  if (/\bblind(e|er|es|en)?\s+(augen|sparschwein|haushalt|verwaltung|planung|politik|ampel|stadt)\b/.test(n)) return true;
  if (/\b(taub(e|er|es|en)?|lahm(e|er|es|en)?|krank(e|er|es|en)?|hilflos(e|er|es|en)?)\s+(verwaltung|planung|haushalt|politik|ampel|stadt)\b/.test(n)) return true;
  if (/barrierefreiheit.{0,30}\b(luxus|spass|spaß|teurer spass|teurer spaß)\b/.test(n)) return true;
  if (/\b(gefahrenszene|hilflosigkeit|panik|panisch|gefährdet|gefaehrdet|unfallopfer)\b/.test(n)) return true;
  return false;
}

function wouldStillBlock(j) {
  const oldStage = safeStr(j.sharepicNeedStage);
  if (!['topic_error', 'blocked_source_lock'].includes(oldStage)) return { blocked: false };

  const analysis = parseObj(j.analysisJson);
  const fakten = parseObj(j.faktenAgentJson);
  const visualAnchors = parseObj(analysis.visualAnchors);

  // Frisch aus faktenAgentJson ableiten (wie P4s kanonischer Node "Pruefe
  // Source-Lock (Content)"), NICHT das eingefrorene analysisJson.sourceLock
  // verwenden - das wird nur bei einem ERFOLGREICHEN P4-Lauf aktualisiert und
  // bleibt bei dauerhaft blockierten Zeilen auf dem Stand des letzten
  // (blockierten) Laufs stehen, auch wenn faktenAgentJson seither aktuellere
  // Daten enthaelt (2026-07-25, Vorgang 2026/138 als Realfall gefunden).
  const sourceLockErrors = [];
  if (!safeStr(fakten.sourceTopic)) sourceLockErrors.push('sourceTopic fehlt');
  if (asArr(fakten.requiredTerms).length < 2) sourceLockErrors.push('requiredTerms < 2');
  if (fakten.parseError === true) sourceLockErrors.push('faktenAgentJson.parseError ist true');
  if (sourceLockErrors.length > 0) return { blocked: true, reason: 'sourceLock unvollstaendig: ' + sourceLockErrors.join('; ') };
  const sourceLock = {
    sourceTopic: safeStr(fakten.sourceTopic),
    sourceConflict: safeStr(fakten.sourceConflict),
    requiredTerms: asArr(fakten.requiredTerms),
    requiredObjects: asArr(fakten.requiredObjects),
    requiredAction: safeStr(fakten.requiredAction),
    affectedGroups: asArr(fakten.affectedGroups)
  };

  const sprengstoff = norm(firstValue(j.sprengstoff, analysis.sprengstoff));
  const empfehlung = norm(firstValue(j.empfehlung, analysis.empfehlung));
  const relevantScore = num(firstValue(j.relevantScore, analysis.relevantScore, analysis.relevanz));
  const kommunikationspotenzial = num(firstValue(j.kommunikationspotenzial, analysis.kommunikationspotenzial));
  const instagramCarouselNoetig = safeBool(j.instagramCarouselNoetig) || safeBool(analysis.instagramCarouselNoetig);
  const instagramSharepicAngefragt = safeBool(j.instagramSharepicNoetig) || safeBool(analysis.instagramSharepicNoetig);

  const visualRequested = instagramCarouselNoetig || instagramSharepicAngefragt ||
    (empfehlung === 'REAGIEREN' && ['MITTEL', 'HOCH'].includes(sprengstoff)) ||
    relevantScore >= 8 || kommunikationspotenzial >= 8;

  if (!visualRequested) return { blocked: false };

  const anchorErrors = [];
  if (!safeStr(visualAnchors.satireThemaKonkret)) anchorErrors.push('satireThemaKonkret fehlt');
  if (!safeStr(visualAnchors.satireKonfliktKonkret)) anchorErrors.push('satireKonfliktKonkret fehlt');
  if (asArr(visualAnchors.visualPflichtobjekte).length < 2) anchorErrors.push('visualPflichtobjekte < 2');
  if (!safeStr(visualAnchors.visualPflichthandlung)) anchorErrors.push('visualPflichthandlung fehlt');
  if (!safeStr(visualAnchors.visualErkennungssatz)) anchorErrors.push('visualErkennungssatz fehlt');
  if (!safeStr(visualAnchors.visualUeberzeichnung)) anchorErrors.push('visualUeberzeichnung fehlt');
  if (asArr(visualAnchors.visualVerboteneErsatzmotive).length < 2) anchorErrors.push('visualVerboteneErsatzmotive < 2');
  // Wie bei sourceLock (siehe Kommentar oben): NICHT das eingefrorene analysisJson.visualAnchorsValid
  // pruefen, sondern die 7 einzelnen visualAnchors-Felder oben sind bereits die frische Neuableitung
  // (identische Vollstaendigkeitspruefung wie in P3_Bewertungs "Parse Analyse JSON"). Das gefrorene
  // Flag stammt vom letzten (moeglicherweise blockierten) Lauf und kann veraltet sein, auch wenn die
  // Felder selbst laengst vollstaendig sind (2026-07-25, Vorgang 2026/109-01 als Realfall gefunden).
  if (anchorErrors.length > 0) return { blocked: true, reason: 'VisualAnchors unvollstaendig: ' + anchorErrors.join('; ') };

  const sourceStrictText = [j.title, j.vorgangsnummer, j.summaryText, j.combinedText].map(safeStr).join('\n');
  const sourceNorm = normText(sourceStrictText);
  const sensitiveContext = SENSITIVE_CONTEXT_RE.test(normText(sourceStrictText + ' ' + asArr(sourceLock.affectedGroups).join(' ')));

  const sensitiveObjectsFound = sensitiveContext ? [
    ...asArr(visualAnchors.visualPflichtobjekte).filter(isSensitivePersonObject),
    ...asArr(sourceLock.requiredObjects).filter(isSensitivePersonObject)
  ] : [];
  const forbiddenSymbolsFound = [
    ...asArr(visualAnchors.visualPflichtobjekte).filter(v => isForbiddenSymbol(v, sourceNorm)),
    ...asArr(sourceLock.requiredObjects).filter(v => isForbiddenSymbol(v, sourceNorm))
  ];
  const visualText = [
    visualAnchors.visualUeberzeichnung, visualAnchors.visualErkennungssatz, analysis.visualMetaphor,
    analysis.satireBrief, analysis.satireAngle, asArr(analysis.satirePunchlines).join(' '),
    analysis.moeglicheSatirischeReaktion
  ].map(safeStr).join(' ');

  if (sensitiveObjectsFound.length > 0) return { blocked: true, reason: 'Guard blockiert: Sensible Betroffene als Pflichtobjekt/sourceLock.requiredObject erkannt: ' + sensitiveObjectsFound.join(', ') };
  if (forbiddenSymbolsFound.length > 0) return { blocked: true, reason: 'Guard blockiert: Symbol-Drift als Pflichtobjekt/sourceLock.requiredObject erkannt: ' + forbiddenSymbolsFound.join(', ') };
  if (hasSensitiveMetaphor(visualText, sensitiveContext)) return { blocked: true, reason: 'Guard blockiert: sensible Metapher in Visual-/Satirefeldern erkannt' };
  return { blocked: false };
}

function vnCode(v) { return safeStr(v).replace(/[^0-9A-Za-z]+/g, '-').replace(/^-+|-+$/g, ''); }
function normCode(v) { return safeStr(v).toLowerCase().replace(/^#/, '').replace(/\s+/g, ''); }

const waitingRows = $('Finde wartende Blockaden').all().map(i => i.json || {});
const byCode = new Map();
for (const row of waitingRows) {
  const code = normCode(vnCode(row.vorgangsnummer) || vnCode(row.vorgangKey));
  if (code) byCode.set(code, row);
}

const chunk = Array.isArray(items[0].json.chunk) ? items[0].json.chunk : [];
const matches = [];
// FIX 2026-07-25: unerkannte Codes (Tippfehler, bereits erledigter Vorgang, falsche
// Vorgangsnummer) wurden bisher komplett stillschweigend ignoriert - der Nutzer wusste nie,
// ob seine Antwort ueberhaupt gelesen wurde. Jetzt zumindest eine Rueckmeldung, wenn eine
// Nachricht wie ein -OK/-SKIP-Code aussieht, aber zu keiner aktuell offenen Blockade passt.
const unmatched = [];
for (const ev of chunk) {
  if (!ev || ev.type !== 'm.room.message') continue;
  const content = ev.content || {};
  if (content.msgtype !== 'm.text') continue;
  const ts = Number(ev.origin_server_ts || 0);
  const replyNorm = normCode(content.body);
  if (!replyNorm) continue;

  let action = null, code = null;
  if (replyNorm.endsWith('-ok')) { action = 'ok'; code = replyNorm.slice(0, -3); }
  else if (replyNorm.endsWith('-skip')) { action = 'skip'; code = replyNorm.slice(0, -5); }
  if (!action) continue;

  const row = byCode.get(code);
  if (!row) { unmatched.push({ ts, action, code }); continue; }
  matches.push({ ts, action, row });
}

if (matches.length === 0) {
  if (unmatched.length === 0) return [];
  unmatched.sort((a, b) => a.ts - b.ts);
  const missed = unmatched[0];
  return [{
    json: {
      _skipWrite: true,
      _matrixAction: 'block_reply_no_match',
      _confirmMessage: '⚠️ "' + missed.code + '-' + missed.action.toUpperCase() + '" passt zu keiner aktuell offenen Blockade. Möglich: Vorgangsnummer falsch/vertippt, oder die Zeile ist inzwischen aus einem anderen Grund nicht mehr in der Blockaden-Warteliste.',
      _confirmTxnId: 'blk_confirm_nomatch_' + safeStr(missed.code).replace(/[^a-zA-Z0-9]/g, '') + '_' + Date.now()
    }
  }];
}

matches.sort((a, b) => a.ts - b.ts);
const chosen = matches[0];
const vorgangKeySafe = safeStr(chosen.row.vorgangKey).replace(/[^a-zA-Z0-9]/g, '');

if (chosen.action === 'skip') {
  return [{
    json: {
      ...chosen.row,
      sharepicNeedStage: 'not_applicable',
      visualPromptStage: '',
      visualDecisionReason: 'Manuell per Matrix (-SKIP) als "kein Sharepic" markiert',
      imagePrompt: '', imageHeadline: '', imageSubline: '', imageNegativePrompt: '', visualJson: '{}',
      imageStage: safeStr(chosen.row.imageFinalPath) ? 'composed' : 'not_started',
      _skipWrite: false,
      _matrixAction: 'block_skip',
      _confirmMessage: '☑️ Ok, für ' + safeStr(chosen.row.vorgangsnummer) + ' - ' + safeStr(chosen.row.title) + ' wird dauerhaft kein Sharepic erzeugt. Text-Content läuft normal weiter.',
      _confirmTxnId: 'blk_confirm_' + vorgangKeySafe + '_skip_' + Date.now()
    }
  }];
}

// action === 'ok': frisch pruefen, kein Guard wird umgangen
const result = wouldStillBlock(chosen.row);
if (result.blocked) {
  return [{
    json: {
      ...chosen.row,
      _skipWrite: true,
      _matrixAction: 'block_recheck_still_blocked',
      _confirmMessage: '⛔ ' + safeStr(chosen.row.vorgangsnummer) + ' - ' + safeStr(chosen.row.title) + ' ist immer noch blockiert. Grund: ' + result.reason,
      _confirmTxnId: 'blk_confirm_' + vorgangKeySafe + '_stillblocked_' + Date.now()
    }
  }];
}

const okAnalysis = parseObj(chosen.row.analysisJson);
const okFakten = parseObj(chosen.row.faktenAgentJson);
const okSourceLock = {
  sourceTopic: safeStr(okFakten.sourceTopic),
  sourceConflict: safeStr(okFakten.sourceConflict),
  requiredTerms: asArr(okFakten.requiredTerms),
  requiredObjects: asArr(okFakten.requiredObjects),
  requiredAction: safeStr(okFakten.requiredAction),
  affectedGroups: asArr(okFakten.affectedGroups)
};
const okAnalysisJson = JSON.stringify({ ...okAnalysis, sourceLock: okSourceLock, sourceLockValid: true });

return [{
  json: {
    ...chosen.row,
    analysisJson: okAnalysisJson,
    sharepicNeedStage: 'topic_ok',
    visualPromptStage: 'needs_prompt',
    visualDecisionReason: 'Manuell per Matrix (-OK) erneut geprueft: nicht mehr blockiert',
    imagePrompt: '', imageHeadline: '', imageSubline: '', imageNegativePrompt: '', visualJson: '{}',
    imageStage: safeStr(chosen.row.imageFinalPath) ? 'composed' : 'not_started',
    _skipWrite: false,
    _matrixAction: 'block_recheck_ok',
    _confirmMessage: '✅ ' + safeStr(chosen.row.vorgangsnummer) + ' - ' + safeStr(chosen.row.title) + ' ist nicht mehr blockiert und wird jetzt fuer den Bild-Prompt freigegeben.',
    _confirmTxnId: 'blk_confirm_' + vorgangKeySafe + '_recheckok_' + Date.now()
  }
}];

// FIX 2026-08-01 (Nutzerwunsch): zeichnet die tatsaechliche menschliche Entscheidung
// (nicht nur das automatisierte QA-Agent-Verdikt) als Lernbeispiel auf. qaStage='headline_choice'
// haelt diese Beispiele getrennt von den QA-Agent-Beispielen (qaStage='analyse'), damit spaeter
// gezielt danach gefiltert werden kann (siehe P3e "Lern-Agent: Hole Kopfzeilen-Beispiele").
function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function parseArr(v) {
  if (Array.isArray(v)) return v;
  try { const p = JSON.parse(String(v || '[]')); return Array.isArray(p) ? p : []; } catch (e) { return []; }
}

const row = $json;
const candidates = parseArr(row._learnAllCandidates);
const chosenCode = safeStr(row._learnChosenCode);
const isReroll = row._matrixAction === 'reroll';

const candidateLines = candidates.map(c => safeStr(c.code) + ': ' + safeStr(c.imageHeadline) + ' - ' + safeStr(c.imageSubline));

let exampleSummary;
if (isReroll) {
  exampleSummary = safeStr(row.title) + ' - Nutzer hat ALLE ' + candidates.length + ' Kandidaten abgelehnt (Reroll angefordert). Angebotene Varianten:\n' + candidateLines.join('\n');
} else {
  const chosen = candidates.find(c => safeStr(c.code) === chosenCode) || {};
  exampleSummary = safeStr(row.title) + ' - Nutzer waehlte ' + chosenCode + ': "' + safeStr(chosen.imageHeadline) + '" - "' + safeStr(chosen.imageSubline) + '". Alle angebotenen Varianten:\n' + candidateLines.join('\n');
}

return {
  json: {
    lernAction: 'record',
    vorgangKey: safeStr(row.vorgangKey),
    vorgangsnummer: safeStr(row.vorgangsnummer),
    qaStage: 'headline_choice',
    source: 'human_headline_choice',
    outcome: isReroll ? 'all_rejected' : 'selected',
    exampleSummary: exampleSummary.slice(0, 2000),
    detailsJson: JSON.stringify({ chosenCode, candidates })
  }
};
